/**
 * MySQL 8 schema (Drizzle). Migrations in /drizzle are generated from this
 * file with `npm run db:generate`; never edit a migration that has shipped.
 *
 * Conventions
 * - Every timestamp is UTC (the pool runs with timezone "Z"); columns are DATETIME(3).
 * - Money is BIGINT minor units (cents/pence). Exchange rates are DECIMAL(18,8).
 * - IDs are UUID strings generated by the app, except small reference lists.
 * - Only lib/dal/** may import this file or the connection. A test enforces it.
 */
import { randomUUID } from "node:crypto";
import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  char,
  check,
  date,
  datetime,
  decimal,
  index,
  int,
  json,
  mysqlEnum,
  mysqlTable,
  primaryKey,
  smallint,
  text,
  tinyint,
  uniqueIndex,
  varchar,
} from "drizzle-orm/mysql-core";
import { MODULES, SCOPES } from "../permissions";

const id = () => varchar("id", { length: 36 }).primaryKey().$defaultFn(() => randomUUID());
const createdAt = () => datetime("created_at", { mode: "date", fsp: 3 }).notNull().$defaultFn(() => new Date());
const updatedAt = () =>
  datetime("updated_at", { mode: "date", fsp: 3 })
    .notNull()
    .$defaultFn(() => new Date())
    .$onUpdateFn(() => new Date());
const userRef = (name: string) => varchar(name, { length: 36 });

// ---------------------------------------------------------------- settings
export const settings = mysqlTable("settings", {
  id: tinyint("id").primaryKey().default(1), // singleton row
  companyName: varchar("company_name", { length: 120 }).notNull().default("CoreNovaIT"),
  baseCurrency: char("base_currency", { length: 3 }).notNull().default("AUD"),
  timezone: varchar("timezone", { length: 64 }).notNull().default("Australia/Sydney"),
  updatedAt: datetime("updated_at", { mode: "date", fsp: 3 }),
  updatedBy: userRef("updated_by"),
});

// ---------------------------------------------------------------- roles and permissions
export const rolePresets = mysqlTable("role_presets", {
  id: varchar("id", { length: 32 }).primaryKey(),
  name: varchar("name", { length: 60 }).notNull(),
  description: varchar("description", { length: 300 }).notNull().default(""),
  sort: smallint("sort").notNull().default(100),
});

const permColumns = {
  module: mysqlEnum("module", MODULES).notNull(),
  canView: boolean("can_view").notNull().default(false),
  canCreate: boolean("can_create").notNull().default(false),
  canEdit: boolean("can_edit").notNull().default(false),
  canDelete: boolean("can_delete").notNull().default(false),
  canExport: boolean("can_export").notNull().default(false),
  scope: mysqlEnum("scope", SCOPES).notNull().default("own"),
};

export const presetPermissions = mysqlTable(
  "preset_permissions",
  {
    presetId: varchar("preset_id", { length: 32 })
      .notNull()
      .references(() => rolePresets.id, { onDelete: "cascade" }),
    ...permColumns,
  },
  (t) => [primaryKey({ columns: [t.presetId, t.module] })]
);

// ---------------------------------------------------------------- users and auth
export const users = mysqlTable(
  "users",
  {
    id: id(),
    email: varchar("email", { length: 254 }).notNull(),
    fullName: varchar("full_name", { length: 120 }).notNull().default(""),
    jobTitle: varchar("job_title", { length: 120 }).notNull().default(""),
    /** 'custom' means the matrix was edited by hand and no longer follows a preset */
    presetId: varchar("preset_id", { length: 32 })
      .notNull()
      .default("staff")
      .references(() => rolePresets.id),
    /** invited: has no password yet. deactivated: cannot sign in. */
    status: mysqlEnum("status", ["invited", "active", "deactivated"]).notNull().default("invited"),
    /** argon2id; null until the invite is accepted */
    passwordHash: varchar("password_hash", { length: 255 }),
    passwordChangedAt: datetime("password_changed_at", { mode: "date", fsp: 3 }),
    /** true for admins and anyone with finance, transactions, team, settings or audit access */
    mfaRequired: boolean("mfa_required").notNull().default(false),
    /** AES-256-GCM encrypted TOTP secret (see lib/auth/crypto.ts) */
    totpSecretEnc: varchar("totp_secret_enc", { length: 255 }),
    /** secret shown during setup, not yet confirmed with a code */
    totpPendingEnc: varchar("totp_pending_enc", { length: 255 }),
    totpEnabledAt: datetime("totp_enabled_at", { mode: "date", fsp: 3 }),
    /** last accepted 30-second step, so a code can't be replayed */
    totpLastStep: bigint("totp_last_step", { mode: "number" }),
    failedLogins: smallint("failed_logins").notNull().default(0),
    lockedUntil: datetime("locked_until", { mode: "date", fsp: 3 }),
    lastSignInAt: datetime("last_sign_in_at", { mode: "date", fsp: 3 }),
    invitedBy: userRef("invited_by"),
    /** send notifications by email too (in-app ones always appear) */
    notifyEmail: boolean("notify_email").notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("users_email_uq").on(t.email), index("users_preset_idx").on(t.presetId)]
);

export const userPermissions = mysqlTable(
  "user_permissions",
  {
    userId: userRef("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    ...permColumns,
  },
  (t) => [primaryKey({ columns: [t.userId, t.module] })]
);

/** Server-side sessions. The cookie holds a random token; only its SHA-256 is stored. */
export const sessions = mysqlTable(
  "sessions",
  {
    id: char("id", { length: 64 }).primaryKey(), // sha256(token) hex
    userId: userRef("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
    lastSeenAt: datetime("last_seen_at", { mode: "date", fsp: 3 }).notNull(),
    expiresAt: datetime("expires_at", { mode: "date", fsp: 3 }).notNull(),
    /** set once the TOTP or a recovery code was accepted in this session */
    mfaVerifiedAt: datetime("mfa_verified_at", { mode: "date", fsp: 3 }),
    ip: varchar("ip", { length: 45 }),
    userAgent: varchar("user_agent", { length: 255 }),
  },
  (t) => [index("sessions_user_idx").on(t.userId), index("sessions_expires_idx").on(t.expiresAt)]
);

/** Single-use invite and password-reset links. Only the token's SHA-256 is stored. */
export const authTokens = mysqlTable(
  "auth_tokens",
  {
    id: char("id", { length: 64 }).primaryKey(), // sha256(token) hex
    userId: userRef("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    purpose: mysqlEnum("purpose", ["invite", "reset"]).notNull(),
    expiresAt: datetime("expires_at", { mode: "date", fsp: 3 }).notNull(),
    usedAt: datetime("used_at", { mode: "date", fsp: 3 }),
    createdAt: createdAt(),
  },
  (t) => [index("auth_tokens_user_idx").on(t.userId)]
);

/** One-time two-factor recovery codes, stored as SHA-256 hashes. */
export const recoveryCodes = mysqlTable(
  "recovery_codes",
  {
    id: int("id").autoincrement().primaryKey(),
    userId: userRef("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    codeHash: char("code_hash", { length: 64 }).notNull(),
    usedAt: datetime("used_at", { mode: "date", fsp: 3 }),
    createdAt: createdAt(),
  },
  (t) => [index("recovery_codes_user_idx").on(t.userId)]
);

// ---------------------------------------------------------------- audit log (append-only)
export const auditLog = mysqlTable(
  "audit_log",
  {
    id: bigint("id", { mode: "number", unsigned: true }).autoincrement().primaryKey(),
    at: datetime("at", { mode: "date", fsp: 3 }).notNull().$defaultFn(() => new Date()),
    actorId: userRef("actor_id"), // no FK: the history outlives the user
    actorEmail: varchar("actor_email", { length: 254 }),
    action: varchar("action", { length: 32 }).notNull(),
    entity: varchar("entity", { length: 64 }).notNull(),
    entityId: varchar("entity_id", { length: 64 }),
    summary: varchar("summary", { length: 500 }),
    before: json("before"),
    after: json("after"),
    ip: varchar("ip", { length: 45 }),
  },
  (t) => [
    index("audit_at_idx").on(t.at),
    index("audit_actor_idx").on(t.actorId),
    index("audit_entity_idx").on(t.entity, t.entityId),
  ]
);

// ---------------------------------------------------------------- reference lists
export const streams = mysqlTable(
  "streams",
  {
    id: int("id").autoincrement().primaryKey(),
    name: varchar("name", { length: 80 }).notNull(),
    active: boolean("active").notNull().default(true),
    sort: smallint("sort").notNull().default(100),
  },
  (t) => [uniqueIndex("streams_name_uq").on(t.name)]
);

export const countries = mysqlTable("countries", {
  code: varchar("code", { length: 8 }).primaryKey(), // GB, AU, OTHER
  name: varchar("name", { length: 80 }).notNull(),
  sort: smallint("sort").notNull().default(100),
});

/** The expense category list admins edit in Settings. Expenses store the name. */
export const expenseCategories = mysqlTable(
  "expense_categories",
  {
    id: int("id").autoincrement().primaryKey(),
    name: varchar("name", { length: 80 }).notNull(),
    active: boolean("active").notNull().default(true),
    sort: smallint("sort").notNull().default(100),
  },
  (t) => [uniqueIndex("expense_categories_name_uq").on(t.name)]
);

export const representatives = mysqlTable(
  "representatives",
  {
    id: id(),
    name: varchar("name", { length: 120 }).notNull(),
    email: varchar("email", { length: 254 }),
    phone: varchar("phone", { length: 40 }),
    /** 0.1000 = 10% */
    commissionRate: decimal("commission_rate", { precision: 5, scale: 4 }).notNull().default("0"),
    /** optional portal login for this rep; drives the "assigned" scope */
    userId: userRef("user_id").references(() => users.id, { onDelete: "set null" }),
    active: boolean("active").notNull().default(true),
    createdBy: userRef("created_by").references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("reps_user_idx").on(t.userId),
    check("reps_rate_chk", sql`${t.commissionRate} >= 0 and ${t.commissionRate} <= 1`),
  ]
);

// ---------------------------------------------------------------- uploads
/** Metadata for uploaded files. The bytes live in UPLOAD_DIR, outside the web root. */
export const files = mysqlTable(
  "files",
  {
    id: id(),
    /** permission module that governs who may download it */
    module: mysqlEnum("module", MODULES).notNull(),
    entityType: varchar("entity_type", { length: 32 }),
    entityId: varchar("entity_id", { length: 36 }),
    originalName: varchar("original_name", { length: 200 }).notNull(),
    mimeType: varchar("mime_type", { length: 100 }).notNull(),
    sizeBytes: int("size_bytes", { unsigned: true }).notNull(),
    sha256: char("sha256", { length: 64 }).notNull(),
    /** random file name inside UPLOAD_DIR; never derived from user input */
    storageKey: char("storage_key", { length: 32 }).notNull(),
    uploadedBy: userRef("uploaded_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("files_storage_uq").on(t.storageKey), index("files_entity_idx").on(t.entityType, t.entityId)]
);

// ---------------------------------------------------------------- finance core
const money = {
  amountMinor: bigint("amount_minor", { mode: "number" }).notNull(),
  currency: char("currency", { length: 3 }).notNull(),
  fxRateToBase: decimal("fx_rate_to_base", { precision: 18, scale: 8 }).notNull().default("1"),
  /** computed by MySQL: amount in the base currency, rounded half away from zero */
  amountBaseMinor: bigint("amount_base_minor", { mode: "number" }).generatedAlwaysAs(
    sql`round(\`amount_minor\` * \`fx_rate_to_base\`)`,
    { mode: "stored" }
  ),
};

export const incomeEntries = mysqlTable(
  "income_entries",
  {
    id: id(),
    entryDate: date("entry_date", { mode: "string" }).notNull(),
    streamId: int("stream_id")
      .notNull()
      .references(() => streams.id),
    countryCode: varchar("country_code", { length: 8 })
      .notNull()
      .references(() => countries.code),
    client: varchar("client", { length: 200 }).notNull().default(""),
    description: varchar("description", { length: 500 }).notNull().default(""),
    ...money,
    invoiceRef: varchar("invoice_ref", { length: 80 }),
    status: mysqlEnum("status", ["pending", "paid", "overdue"]).notNull().default("pending"),
    representativeId: varchar("representative_id", { length: 36 }).references(() => representatives.id, {
      onDelete: "set null",
    }),
    /** the representative's rate when the entry was credited, so later rate changes don't rewrite history */
    commissionRate: decimal("commission_rate", { precision: 5, scale: 4 }),
    invoiceFileId: varchar("invoice_file_id", { length: 36 }).references(() => files.id, { onDelete: "set null" }),
    notes: text("notes"),
    isSample: boolean("is_sample").notNull().default(false),
    createdBy: userRef("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("income_date_idx").on(t.entryDate),
    index("income_created_by_idx").on(t.createdBy),
    index("income_rep_idx").on(t.representativeId),
    index("income_status_idx").on(t.status),
    check("income_commission_chk", sql`${t.commissionRate} is null or (${t.commissionRate} >= 0 and ${t.commissionRate} <= 1)`),
    check("income_amount_chk", sql`${t.amountMinor} > 0`),
    check("income_rate_chk", sql`${t.fxRateToBase} > 0`),
    check("income_currency_chk", sql`${t.currency} regexp '^[A-Z]{3}$'`),
  ]
);

export const expenses = mysqlTable(
  "expenses",
  {
    id: id(),
    expenseDate: date("expense_date", { mode: "string" }).notNull(),
    category: varchar("category", { length: 80 }).notNull(),
    vendor: varchar("vendor", { length: 200 }).notNull().default(""),
    description: varchar("description", { length: 500 }).notNull().default(""),
    ...money,
    /** null = a shared cost, counted only when the dashboard shows all countries */
    countryCode: varchar("country_code", { length: 8 }).references(() => countries.code),
    /** set when the expense was created by "mark as paid" on a subscription */
    subscriptionId: varchar("subscription_id", { length: 36 }).references(() => subscriptions.id, { onDelete: "set null" }),
    receiptFileId: varchar("receipt_file_id", { length: 36 }).references(() => files.id, { onDelete: "set null" }),
    isRecurring: boolean("is_recurring").notNull().default(false),
    notes: text("notes"),
    isSample: boolean("is_sample").notNull().default(false),
    createdBy: userRef("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("expense_date_idx").on(t.expenseDate),
    index("expense_created_by_idx").on(t.createdBy),
    index("expense_category_idx").on(t.category),
    check("expense_amount_chk", sql`${t.amountMinor} > 0`),
    check("expense_rate_chk", sql`${t.fxRateToBase} > 0`),
    check("expense_currency_chk", sql`${t.currency} regexp '^[A-Z]{3}$'`),
  ]
);

/**
 * Subscriptions and other upcoming payments. "Mark as paid" records an
 * expense and moves next_due_date on by one billing cycle ("once" ends it).
 */
export const subscriptions = mysqlTable(
  "subscriptions",
  {
    id: id(),
    vendor: varchar("vendor", { length: 200 }).notNull(),
    category: varchar("category", { length: 80 }).notNull(),
    description: varchar("description", { length: 500 }).notNull().default(""),
    ...money,
    billingCycle: mysqlEnum("billing_cycle", ["weekly", "monthly", "quarterly", "yearly", "once"]).notNull().default("monthly"),
    nextDueDate: date("next_due_date", { mode: "string" }).notNull(),
    status: mysqlEnum("status", ["active", "paused", "cancelled", "completed"]).notNull().default("active"),
    /** show the "due soon" warning this many days before the due date */
    reminderDays: smallint("reminder_days").notNull().default(3),
    /** card or account it's paid from, e.g. "Company Visa" */
    paidFrom: varchar("paid_from", { length: 120 }).notNull().default(""),
    /** the person looking after it; drives the "assigned" scope */
    responsibleUserId: userRef("responsible_user_id").references(() => users.id, { onDelete: "set null" }),
    /** null = shared across countries */
    countryCode: varchar("country_code", { length: 8 }).references(() => countries.code),
    notes: text("notes"),
    isSample: boolean("is_sample").notNull().default(false),
    createdBy: userRef("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("sub_due_idx").on(t.status, t.nextDueDate),
    index("sub_created_by_idx").on(t.createdBy),
    check("sub_amount_chk", sql`${t.amountMinor} > 0`),
    check("sub_rate_chk", sql`${t.fxRateToBase} > 0`),
    check("sub_currency_chk", sql`${t.currency} regexp '^[A-Z]{3}$'`),
    check("sub_reminder_chk", sql`${t.reminderDays} between 0 and 90`),
  ]
);

/** Commission paid out to a representative (the payout log). */
export const repPayouts = mysqlTable(
  "rep_payouts",
  {
    id: id(),
    representativeId: varchar("representative_id", { length: 36 })
      .notNull()
      .references(() => representatives.id),
    paidDate: date("paid_date", { mode: "string" }).notNull(),
    ...money,
    reference: varchar("reference", { length: 120 }).notNull().default(""),
    notes: text("notes"),
    isSample: boolean("is_sample").notNull().default(false),
    createdBy: userRef("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("payout_rep_idx").on(t.representativeId),
    index("payout_date_idx").on(t.paidDate),
    check("payout_amount_chk", sql`${t.amountMinor} > 0`),
    check("payout_rate_chk", sql`${t.fxRateToBase} > 0`),
    check("payout_currency_chk", sql`${t.currency} regexp '^[A-Z]{3}$'`),
  ]
);

// ---------------------------------------------------------------- marketing
export const MARKETING_CHANNELS = ["email", "cold_call", "direct", "individual_referral", "social", "other"] as const;
export const MARKETING_OUTCOMES = ["no_response", "replied", "meeting", "deal_won", "deal_lost"] as const;

/** A named push (e.g. "Spring dental clinics email"); activities can belong to one. */
export const campaigns = mysqlTable(
  "campaigns",
  {
    id: id(),
    name: varchar("name", { length: 120 }).notNull(),
    /** the main channel, or null when it mixes channels */
    channel: mysqlEnum("channel", MARKETING_CHANNELS),
    status: mysqlEnum("status", ["planned", "active", "paused", "finished"]).notNull().default("active"),
    startDate: date("start_date", { mode: "string" }),
    endDate: date("end_date", { mode: "string" }),
    description: varchar("description", { length: 500 }).notNull().default(""),
    isSample: boolean("is_sample").notNull().default(false),
    createdBy: userRef("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("campaign_name_uq").on(t.name),
    check("campaign_dates_chk", sql`${t.endDate} is null or ${t.startDate} is null or ${t.endDate} >= ${t.startDate}`),
  ]
);

/**
 * One call, email, referral or other touch, and how it went. occurred_at is
 * UTC; the heatmap and insights read it in the company time zone. A won deal
 * may carry its value (original currency + manual rate, like income).
 */
export const marketingActivities = mysqlTable(
  "marketing_activities",
  {
    id: id(),
    occurredAt: datetime("occurred_at", { mode: "date", fsp: 3 }).notNull(),
    channel: mysqlEnum("channel", MARKETING_CHANNELS).notNull(),
    campaignId: varchar("campaign_id", { length: 36 }).references(() => campaigns.id),
    contactName: varchar("contact_name", { length: 200 }).notNull(),
    contactCompany: varchar("contact_company", { length: 200 }).notNull().default(""),
    outcome: mysqlEnum("outcome", MARKETING_OUTCOMES).notNull(),
    dealValueMinor: bigint("deal_value_minor", { mode: "number" }),
    dealCurrency: char("deal_currency", { length: 3 }),
    dealFxRateToBase: decimal("deal_fx_rate_to_base", { precision: 18, scale: 8 }),
    /** computed by MySQL: the deal value in the base currency, rounded half away from zero */
    dealValueBaseMinor: bigint("deal_value_base_minor", { mode: "number" }).generatedAlwaysAs(
      sql`round(\`deal_value_minor\` * \`deal_fx_rate_to_base\`)`,
      { mode: "stored" }
    ),
    /** who did the outreach; drives the "assigned" scope */
    ownerId: userRef("owner_id")
      .notNull()
      .references(() => users.id),
    notes: text("notes"),
    isSample: boolean("is_sample").notNull().default(false),
    createdBy: userRef("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("mkt_occurred_idx").on(t.occurredAt),
    index("mkt_owner_idx").on(t.ownerId),
    index("mkt_created_by_idx").on(t.createdBy),
    index("mkt_campaign_idx").on(t.campaignId),
    index("mkt_channel_idx").on(t.channel, t.occurredAt),
    // a value only on a won deal, and then all three money fields together
    check(
      "mkt_deal_value_chk",
      sql`(${t.dealValueMinor} is null and ${t.dealCurrency} is null and ${t.dealFxRateToBase} is null) or (${t.outcome} = 'deal_won' and ${t.dealValueMinor} > 0 and ${t.dealCurrency} regexp '^[A-Z]{3}$' and ${t.dealFxRateToBase} > 0)`
    ),
  ]
);

// ---------------------------------------------------------------- calendar
/**
 * Events people create (meetings, deadlines, other). Task deadlines and payment
 * due dates are shown on the calendar from their own tables, not copied here.
 * Times are UTC; an all-day event runs from local midnight to local midnight.
 */
export const events = mysqlTable(
  "events",
  {
    id: id(),
    title: varchar("title", { length: 200 }).notNull(),
    type: mysqlEnum("type", ["meeting", "deadline", "payment", "other"]).notNull().default("meeting"),
    startsAt: datetime("starts_at", { mode: "date", fsp: 3 }).notNull(),
    endsAt: datetime("ends_at", { mode: "date", fsp: 3 }).notNull(),
    allDay: boolean("all_day").notNull().default(false),
    location: varchar("location", { length: 300 }).notNull().default(""),
    videoUrl: varchar("video_url", { length: 500 }).notNull().default(""),
    description: text("description"),
    /** remind this many minutes before (sent once notifications arrive); null = no reminder */
    reminderMinutes: smallint("reminder_minutes"),
    isSample: boolean("is_sample").notNull().default(false),
    createdBy: userRef("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("event_starts_idx").on(t.startsAt),
    index("event_created_by_idx").on(t.createdBy),
    check("event_times_chk", sql`${t.endsAt} >= ${t.startsAt}`),
    check("event_reminder_chk", sql`${t.reminderMinutes} is null or ${t.reminderMinutes} between 0 and 10080`),
  ]
);

/** Who is invited; drives the "assigned" scope (staff see the events they're invited to). */
export const eventAttendees = mysqlTable(
  "event_attendees",
  {
    eventId: varchar("event_id", { length: 36 })
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    userId: userRef("user_id")
      .notNull()
      .references(() => users.id),
  },
  (t) => [primaryKey({ columns: [t.eventId, t.userId] }), index("attendee_user_idx").on(t.userId)]
);

// ---------------------------------------------------------------- tasks
export type ChecklistItem = { id: string; text: string; done: boolean };

export const tasks = mysqlTable(
  "tasks",
  {
    id: id(),
    title: varchar("title", { length: 200 }).notNull(),
    description: text("description"),
    status: mysqlEnum("status", ["todo", "in_progress", "review", "done"]).notNull().default("todo"),
    priority: mysqlEnum("priority", ["low", "medium", "high", "urgent"]).notNull().default("medium"),
    /** who it's for; drives the "assigned" scope and "My tasks" */
    assigneeId: userRef("assignee_id").references(() => users.id),
    dueDate: date("due_date", { mode: "string" }),
    /** short tags, e.g. ["website", "client"] */
    labels: json("labels").$type<string[]>(),
    checklist: json("checklist").$type<ChecklistItem[]>(),
    completedAt: datetime("completed_at", { mode: "date", fsp: 3 }),
    isSample: boolean("is_sample").notNull().default(false),
    createdBy: userRef("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("task_assignee_idx").on(t.assigneeId, t.status),
    index("task_due_idx").on(t.dueDate),
    index("task_created_by_idx").on(t.createdBy),
  ]
);

export const taskComments = mysqlTable(
  "task_comments",
  {
    id: id(),
    taskId: varchar("task_id", { length: 36 })
      .notNull()
      .references(() => tasks.id, { onDelete: "cascade" }),
    authorId: userRef("author_id")
      .notNull()
      .references(() => users.id),
    body: text("body").notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("comment_task_idx").on(t.taskId, t.createdAt)]
);

// ---------------------------------------------------------------- chat
/**
 * Channels (#general plus ones admins create) and direct messages. Reading
 * always needs membership: there is no admin override, so nobody can read a
 * direct message they aren't part of. #general (is_default) includes every
 * active user automatically.
 */
export const chatChannels = mysqlTable(
  "chat_channels",
  {
    id: id(),
    kind: mysqlEnum("kind", ["channel", "dm"]).notNull().default("channel"),
    /** "general", "projects"…; empty for direct messages */
    name: varchar("name", { length: 60 }).notNull().default(""),
    topic: varchar("topic", { length: 200 }).notNull().default(""),
    isDefault: boolean("is_default").notNull().default(false),
    /** the two member ids, sorted and joined, so a pair has exactly one DM */
    dmKey: varchar("dm_key", { length: 80 }),
    archivedAt: datetime("archived_at", { mode: "date", fsp: 3 }),
    isSample: boolean("is_sample").notNull().default(false),
    createdBy: userRef("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("chat_dm_uq").on(t.dmKey), index("chat_kind_idx").on(t.kind, t.name)]
);

export const chatMembers = mysqlTable(
  "chat_members",
  {
    channelId: varchar("channel_id", { length: 36 })
      .notNull()
      .references(() => chatChannels.id, { onDelete: "cascade" }),
    userId: userRef("user_id")
      .notNull()
      .references(() => users.id),
    /** messages after this are unread for this person */
    lastReadAt: datetime("last_read_at", { mode: "date", fsp: 3 }).notNull().$defaultFn(() => new Date()),
    /** set while they type; the typing indicator shows until it passes */
    typingUntil: datetime("typing_until", { mode: "date", fsp: 3 }),
    joinedAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.channelId, t.userId] }), index("chat_member_user_idx").on(t.userId)]
);

export const chatMessages = mysqlTable(
  "chat_messages",
  {
    id: id(),
    channelId: varchar("channel_id", { length: 36 })
      .notNull()
      .references(() => chatChannels.id, { onDelete: "cascade" }),
    authorId: userRef("author_id")
      .notNull()
      .references(() => users.id),
    body: text("body").notNull(),
    fileId: varchar("file_id", { length: 36 }).references(() => files.id, { onDelete: "set null" }),
    editedAt: datetime("edited_at", { mode: "date", fsp: 3 }),
    /** deleted messages keep their place but lose their text and file */
    deletedAt: datetime("deleted_at", { mode: "date", fsp: 3 }),
    isSample: boolean("is_sample").notNull().default(false),
    createdAt: datetime("created_at", { mode: "date", fsp: 3 }).notNull().$defaultFn(() => new Date()),
    /** bumped on every change, so live updates can send edits and deletes too */
    updatedAt: datetime("updated_at", { mode: "date", fsp: 3 }).notNull().$defaultFn(() => new Date()),
  },
  (t) => [index("chat_msg_channel_idx").on(t.channelId, t.createdAt), index("chat_msg_updated_idx").on(t.channelId, t.updatedAt)]
);

/** When each person was last active in the portal (online status). */
export const userPresence = mysqlTable("user_presence", {
  userId: userRef("user_id")
    .primaryKey()
    .references(() => users.id),
  lastSeenAt: datetime("last_seen_at", { mode: "date", fsp: 3 }).notNull(),
});

// ---------------------------------------------------------------- notifications
export const NOTIFICATION_TYPES = ["task_assigned", "task_due", "meeting_reminder", "payment_due", "chat_mention"] as const;

/**
 * In-app notifications (and the email queue: emailed_at is set once sent).
 * dedupe_key is unique, so the scheduler can run as often as it likes
 * without creating the same reminder twice.
 */
export const notifications = mysqlTable(
  "notifications",
  {
    id: id(),
    userId: userRef("user_id")
      .notNull()
      .references(() => users.id),
    type: mysqlEnum("type", NOTIFICATION_TYPES).notNull(),
    title: varchar("title", { length: 200 }).notNull(),
    body: varchar("body", { length: 500 }).notNull().default(""),
    href: varchar("href", { length: 300 }).notNull().default(""),
    dedupeKey: varchar("dedupe_key", { length: 191 }).notNull(),
    readAt: datetime("read_at", { mode: "date", fsp: 3 }),
    emailedAt: datetime("emailed_at", { mode: "date", fsp: 3 }),
    /** emailing was attempted and skipped (setting off, or no mail set up), so it isn't retried */
    emailSkipped: boolean("email_skipped").notNull().default(false),
    createdAt: datetime("created_at", { mode: "date", fsp: 3 }).notNull().$defaultFn(() => new Date()),
  },
  (t) => [uniqueIndex("notif_dedupe_uq").on(t.dedupeKey), index("notif_user_idx").on(t.userId, t.readAt, t.createdAt), index("notif_email_idx").on(t.emailedAt, t.emailSkipped)]
);
